-- Staging-only read-only table count attestation. The psql \gexec sends
-- SELECTs generated by quote-safe format(%I) from the PostgreSQL catalog.
-- The single REPEATABLE READ transaction gives all 183 table counts
-- a consistent MVCC snapshot, unlike 183 separate transactions.
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT format(
  'SELECT jsonb_build_object(''schema'', %L, ''table'', %L, ''rows'', count(*)::bigint)::text FROM %I.%I',
  n.nspname,c.relname,n.nspname,c.relname
)
FROM pg_class c
JOIN pg_namespace n ON n.oid=c.relnamespace
WHERE n.nspname IN ('public','private','powerhub_private')
  AND c.relkind IN ('r','p') AND NOT c.relispartition
ORDER BY n.nspname,c.relname
\gexec
COMMIT;
